function serialize (source, opts) {
  var out = ''
  var key
  var tmp
  var type
  var i

  opts = opts || {}
  if (!opts._visited) {
    opts._visited = []
  }
  if (!opts._refs) {
    opts.references = []
    opts._refs = new Ref(opts.references)
  }

  if (util.isNull(source)) {
    out += 'null'
  } else if (util.isArray(source)) {
    tmp = source.map(function (item) {
      return serialize(item, opts)
    })
    out += '[' + tmp.join(', ') + ']'
  } else if (util.isFunction(source)) {
    tmp = source.toString()
    out += !/^\s*(function|\([^)]*\)\s*=>)/m.test(tmp) ? 'function ' + tmp : tmp
  } else if (util.isObject(source)) {
    if (util.isRegExp(source)) {
      out += 'new RegExp("' + source.source + '", "' + source.flags + '")'
    } else if (util.isDate(source)) {
      out += 'new Date("' + source.toJSON() + '")'
    } else if (util.isError(source)) {
      out += 'new Error(' + (source.message ? '"' + source.message + '"' : '') + ')'
    } else if (util.isBuffer(source)) {
      out += "Buffer.from('" + source.toString('base64') + "', 'base64')"
    } else if ((type = util.isTypedArray(source))) {
      tmp = []
      for (i = 0; i < source.length; i++) {
        tmp.push(source[i])
      }
      out += 'new ' + type + '(' +
        '[' + tmp.join(', ') + ']' +
        ')'
    } else {
      tmp = []
      if (!~opts._visited.indexOf(source)) {
        opts._visited.push(source)
        for (key in source) {
          if (source.hasOwnProperty(key)) {
            if (opts.reference && util.isObject(source[key])) {
              opts._refs.push(key)
              if (!opts._refs.hasReference(source[key])) {
                tmp.push(Ref.wrapkey(key) + ': ' + serialize(source[key], opts))
              }
              opts._refs.pop()
            } else {
              tmp.push(Ref.wrapkey(key) + ': ' + serialize(source[key], opts))
            }
          }
        }
        out += '{' + tmp.join(', ') + '}'
        opts._visited.pop()
      } else {
        if (opts.ignoreCircular) {
          out += '{/*[Circular]*/}'
        } else {
          throw new Error('can not convert circular structures.')
        }
      }
    }
  } else if (util.isString(source)) {
    out += '"' + (opts.unsafe ? util.unsafeString(source) : util.safeString(source)) + '"'
  } else {
    out += '' + source
  }
  return out
}

function simplePurifier(
    text,
    bHtml = false,
    bSvg = false,
    bSvgFilters = false
)
{
    return sanitizeDom(
        DOMPurify.sanitize(
            text
                .replaceAll('&lt;', '<')
                .replaceAll('&#x3C;', '<')
                .replaceAll('&#x3c;', '<')
                .replaceAll('&#60;', '<')
                .replaceAll('&gt;', '>')
                .replaceAll('&#x3E;', '>')
                .replaceAll('&#x3e;', '>')
                .replaceAll('&#62;', '>')
                .replaceAll('&amp;', '&')
                .replaceAll('&#38;', '&')
                .replaceAll('&#x26;', '&')
                .replaceAll('&quot;', '"')
                .replaceAll('&#34;;', '"')
                .replaceAll('&#x22;', '"')
                .replaceAll('&#39;', "'"),
            {USE_PROFILES: {html:bHtml, svg:bSvg, svgFilters: bSvgFilters}}
        )
    );
}

function escapeArgForQuoted(arg) {
  return arg
    .replace(/[\0\u0008\u001B\u009B]/gu, "")
    .replace(/\r?\n|\r/gu, " ")
    .replace(/%/gu, "^%")
    .replace(/"/gu, `""`);
}

function _makeSetter(property, next) {
	if (
		property === '__proto__' ||
		property === 'constructor' ||
		property === 'prototype'
	) {
		throw new Error('unable to access __proto__, constructor, prototype');
	}

	if (next) {
		return function setter(ctx, value) {
			var t = ctx[property];

			if (!t) {
				t = ctx[property] = {};
			}

			return next(t, value);
		};
	} else {
		return function (ctx, value) {
			ctx[property] = value;
			return ctx;
		};
	}
}

